use std::fmt;
use std::str::FromStr;

#[derive(Debug, PartialEq)]
struct Version {
    major: u8,
    minor: u8,
    patch: u8,
}

impl fmt::Display for Version {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}.{}.{}", self.major, self.minor, self.patch)
    }
}

impl FromStr for Version {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 3 {
            return Err(format!("需要三段版本号: {}", s));
        }
        let parse = |p: &str| p.parse::<u8>().map_err(|_| format!("非法段: {}", p));
        Ok(Version { major: parse(parts[0])?, minor: parse(parts[1])?, patch: parse(parts[2])? })
    }
}

fn main() {
    let v = Version { major: 1, minor: 2, patch: 3 };
    let text = v.to_string();
    println!("{}", text);
    let back: Result<Version, _> = text.parse();
    println!("{:?}", back);
    let bad: Result<Version, _> = "1.2".parse();
    println!("{:?}", bad);
}

