            }
            sender.send(Message::Done { worker }).unwrap();
        }));
    }
    drop(tx);

    let mut total = 0;
    let mut done = Vec::new();
    for message in rx {
        match message {
            Message::Work { value, .. } => total += value,
            Message::Done { worker } => done.push(worker),
        }
    }
    for handle in handles {
        handle.join().unwrap();
    }
    done.sort();
    println!("total={}", total);
    println!("done={:?}", done);
}

