use std::sync::atomic::{AtomicBool, Ordering};

struct Flag(AtomicBool);

impl Flag {
    fn new() -> Self {
        Flag(AtomicBool::new(false))
    }

    fn set_true(&self) {
        self.0.store(true, Ordering::SeqCst);
    }

    fn is_set(&self) -> bool {
        self.0.load(Ordering::SeqCst)
    }
}

fn main() {
    let flag = Flag::new();
