        // recv_timeout waits for a real deadline; it does not order the polls.
        let (hold_open, clock) = mpsc::channel::<()>();
        assert!(matches!(clock.recv_timeout(delay), Err(mpsc::RecvTimeoutError::Timeout)));
        drop(hold_open);
        assert!(event.complete(label));
    });
    (future, producer)
}

// Sequential collection: B is not polled until A has completed.
fn block_on_all<F: Future>(futures: Vec<F>) -> (Vec<F::Output>, usize) {
    let mut results = Vec::new();
    let mut wakes = 0;
    for future in futures {
        let notify = Notify::new();
        results.push(block_on(future, Arc::clone(&notify)));
        wakes += notify.wakes.load(Ordering::SeqCst);
    }
    (results, wakes)
}

fn main() {
    let (first, producer_a) = timer_event("A fired", std::time::Duration::from_millis(2));
    let (second, producer_b) = timer_event("B fired", std::time::Duration::from_millis(2));
    // Both threads exist, but each deadline begins only when its own future
    // is first polled and registers its first-Pending handshake.
    let (results, wakes) = block_on_all(vec![first, second]);
    producer_a.join().unwrap();
    producer_b.join().unwrap();
    assert_eq!(results, vec!["A fired", "B fired"]);
    assert_eq!(wakes, 2);
    for message in results { println!("{message}"); }
    println!("total_wake_calls={wakes}");
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn generic_collection_also_accepts_empty_and_immediately_ready_futures() {
        let (empty, wakes) = block_on_all(Vec::<std::future::Ready<i32>>::new());
        assert!(empty.is_empty());
        assert_eq!(wakes, 0);
        assert_eq!(block_on_all(vec![std::future::ready(3), std::future::ready(4)]), (vec![3, 4], 0));
    }
}

