// T088 目录遍历与文件信息。
//
// os.ReadDir 返回目录条目并按文件名排序，因此输出天然确定。
// 用 FileInfo 可拿到名称、大小、是否为目录等元数据。
//
// 注意：目录条目的 Size() 是**文件系统相关**的值（Linux 上常见 4096，
// Windows 上常见 0），不能作为确定性输出。因此本示例对目录只打印类型，
// 只对普通文件打印大小——这样跨平台输出一致。
package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	dir, err := os.MkdirTemp("", "qfli-t088-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	// 建两个文件和一个子目录，用于演示“是否目录”的判断。
	mustWrite(filepath.Join(dir, "alpha.txt"), "a")
	mustWrite(filepath.Join(dir, "beta.txt"), "bb")
	if err := os.Mkdir(filepath.Join(dir, "sub"), 0o755); err != nil {
		panic(err)
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		panic(err)
	}
	// ReadDir 已按名字排序：alpha.txt, beta.txt, sub。
	for _, e := range entries {
		if e.IsDir() {
			// 目录不打印易变的 size。
			fmt.Printf("%-10s dir\n", e.Name())
			continue
		}
		info, err := e.Info()
		if err != nil {
			panic(err)
		}
		fmt.Printf("%-10s file size=%d\n", e.Name(), info.Size())
	}
}

func mustWrite(path, content string) {
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		panic(err)
	}
}

// T089 JSON 一：Marshal/Unmarshal 基础。
//
// encoding/json 在 Go 值与 JSON 文本之间转换。Marshal 把结构体转成 JSON
// 字节；Unmarshal 把 JSON 解析回结构体。结构体字段必须是导出的（首字母大写）
// 才会被编码，否则会被忽略。
package main

import (
	"encoding/json"
	"fmt"
)

// Profile 是要被编解码的结构体。字段都导出。
type Profile struct {
	Name    string   `json:"name"`
	Age     int      `json:"age"`
	Hobbies []string `json:"hobbies"`
}

func main() {
	p := Profile{
		Name:    "gopher",
		Age:     15,
		Hobbies: []string{"coding", "reading"},
	}

	// 结构体 -> JSON。
	data, err := json.Marshal(p)
	if err != nil {
		panic(err)
	}
	fmt.Println("marshal:", string(data))

	// JSON -> 结构体。
	var back Profile
	if err := json.Unmarshal(data, &back); err != nil {
		panic(err)
	}
	fmt.Println("unmarshal name:", back.Name)
	fmt.Println("unmarshal age:", back.Age)
	fmt.Println("unmarshal hobbies:", back.Hobbies)

	// 往返一致：编码再解码应得到相等结构（切片需用元素比较）。
	again, _ := json.Marshal(back)
	fmt.Println("round-trip stable:", string(again) == string(data))
}

// T090 JSON 二：struct tag、omitempty 与自定义名称。
//
// struct tag 控制 JSON 字段名、是否省略空值、是否忽略字段等。
// omitempty 在字段为零值时省略该键；"-" 表示完全忽略；自定义名字改变键名。
// 本示例展示三种行为，输出确定。
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Account 演示 tag 的常见用法。
type Account struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Password string `json:"-"`                    // 永不序列化
	Email    string `json:"email,omitempty"`      // 空则省略
	Nickname string `json:"nick_name,omitempty"`  // 改名 + 空则省略
	Balance  int    `json:"balance"`              // 零值也保留
}

func main() {
	a := Account{ID: 7, Name: "alice"}
	data, _ := json.Marshal(a)
	fmt.Println("minimal:", string(data))

	// 填入可选字段后，omitempty 的键出现。
	a.Email = "alice@example.com"
	a.Nickname = "ali"
	a.Balance = 100
	data2, _ := json.Marshal(a)
	fmt.Println("filled: ", string(data2))

	// Password 设为非空也永远不会出现在 JSON 中。
	a.Password = "secret"
	data3, _ := json.Marshal(a)
	fmt.Println("password hidden:", !strings.Contains(string(data3), "secret"))
}

// T091 JSON 三：流式 Decoder/Encoder 与未知字段。
//
// json.Decoder 可以连续解码一个流中的多个 JSON 值（如 NDJSON），
// 比 Unmarshal 更适合逐步读取；Decoder.DisallowUnknownFields 会让
// 未知字段报错，便于严格校验。
// 本示例演示：连续解码多个对象、忽略未知字段（默认行为）。
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// Event 是流中的一个事件对象。
type Event struct {
	Type string `json:"type"`
	Code int    `json:"code"`
}

func main() {
	// 一个"流"里包含三个 JSON 对象，其中第二个还有未知字段 extra。
	stream := `{"type":"start","code":1}
{"type":"tick","code":2,"extra":"ignored"}
{"type":"stop","code":3}`

	dec := json.NewDecoder(strings.NewReader(stream))
	count := 0
	for dec.More() {
		var e Event
		// 默认忽略未知字段，因此第二行能成功解码。
		if err := dec.Decode(&e); err != nil {
			panic(err)
		}
		count++
		fmt.Printf("event %d: type=%s code=%d\n", count, e.Type, e.Code)
	}
	fmt.Println("decoded events:", count)

	// 严格模式：未知字段会报错。
	strict := json.NewDecoder(strings.NewReader(`{"type":"x","code":9,"bogus":true}`))
	strict.DisallowUnknownFields()
	var e Event
	err := strict.Decode(&e)
	fmt.Println("strict decode rejected unknown field:", err != nil)
}

// T092 时间一：time.Time、Duration 与格式化。
//
// Go 的时间格式化不使用格式串（如 yyyy-MM-dd），而是用一个"参考时间"
// 2006-01-02 15:04:05 作为布局。本示例使用固定时区与固定时间，
// 因此输出完全确定，不依赖当前时刻。
package main

import (
	"fmt"
	"time"
)

func main() {
	// 固定时区 UTC，构造一个确定的时间点。
	loc := time.UTC
	t := time.Date(2026, 10, 12, 14, 30, 45, 0, loc)

	// 参考布局 "2006-01-02 15:04:05"。
	fmt.Println("formatted:", t.Format("2006-01-02 15:04:05"))
	fmt.Println("date only:", t.Format("2006-01-02"))
	fmt.Println("RFC3339:  ", t.Format(time.RFC3339))

	// 解析：布局必须与实际字符串一致，否则报错。
	parsed, err := time.ParseInLocation("2006-01-02 15:04:05", "2020-01-02 03:04:05", loc)
	if err != nil {
		panic(err)
	}
	fmt.Println("parsed:", parsed.Format(time.RFC3339))

	// Duration 运算：纯时长加减，与墙钟无关。
	d := 90 * time.Minute
	fmt.Println("duration:", d)
	fmt.Println("duration minutes:", d.Minutes())

	later := t.Add(d)
	diff := later.Sub(t)
	fmt.Println("add 90m ->", later.Format("15:04:05"))
	fmt.Println("diff == 90m:", diff == d)
}

// T093 时间二：定时器、Ticker 与单调时钟。
//
// time.Timer 触发一次；time.Ticker 周期性触发。二者都基于单调时钟，
// 不受系统墙钟调整影响。本示例只断言"触发的次数"，不比较实际耗时，
// 因此输出确定、可离线验证。
package main

import (
	"fmt"
	"time"
)

func main() {
	// Timer：一次性。等待其通道被触发。
	timer := time.NewTimer(1 * time.Millisecond)
	<-timer.C
	fmt.Println("timer fired once")

	// Ticker：周期性。计数到 3 次后停止。
	ticker := time.NewTicker(1 * time.Millisecond)
	defer ticker.Stop()

	count := 0
	for range ticker.C {
		count++
		if count == 3 {
			break
		}
	}
	fmt.Println("ticker fired count:", count)

	// 停止后的 Ticker 不再触发（用 select+default 非阻塞探测，结果确定）。
	ticker.Stop()
	select {
	case <-ticker.C:
		fmt.Println("unexpected tick after stop")
	default:
		fmt.Println("no tick after stop")
	}

	// 演示 Now 的单调性：两次调用取差值为正（不断言具体数值）。
	start := time.Now()
	elapsed := time.Since(start)
	fmt.Println("elapsed is non-negative:", elapsed >= 0)
}

// T094 正则一：regexp 匹配与子匹配。
//
// regexp.MustCompile 在正则非法时 panic，适合包级常量；FindStringSubmatch
// 返回整体匹配与各捕获组。本示例从固定字符串中提取结构化字段，输出确定。
package main

import (
	"fmt"
	"regexp"
)

func main() {
	// 匹配形如 "key=value" 的日志片段，捕获 key 与 value。
	re := regexp.MustCompile(`(\w+)=(\w+)`)

	line := "user=alice role=admin active=true"
	// 找出所有匹配。
	all := re.FindAllStringSubmatch(line, -1)
	fmt.Println("matches:", len(all))
	for _, m := range all {
		// m[0] 是整体，m[1]/m[2] 是捕获组。
		fmt.Printf("  key=%-8s value=%s\n", m[1], m[2])
	}

	// 单个匹配。
	one := re.FindStringSubmatch("host=node1")
	fmt.Println("single full match:", one[0])
	fmt.Println("single group1:", one[1])
	fmt.Println("single group2:", one[2])

	// 无匹配时返回 nil；这里做存在性判断。
	fmt.Println("no match is nil:", re.FindStringSubmatch("nokv") == nil)
}

// T095 正则二：替换、分割与预编译复用。
//
// ReplaceAllStringFunc 允许用函数动态决定每个匹配的替换值；
// Split 用正则切分；预编译（MustCompile 到包级变量）避免重复编译。
// 本示例输出确定。
package main

import (
	"fmt"
	"regexp"
)

// 包级预编译：只编译一次，整个程序复用。
var (
	numberRe = regexp.MustCompile(`\d+`)
	spaceRe  = regexp.MustCompile(`\s+`)
)

func main() {
	src := "a1 b22 c333"

	// 条件替换：把每个数字 n 替换为 n*2 的字符串。
	doubled := numberRe.ReplaceAllStringFunc(src, func(m string) string {
		// m 一定是数字串，这里手工解析以避免引入 strconv 干扰阅读。
		n := 0
		for _, r := range m {
			n = n*10 + int(r-'0')
		}
		return fmt.Sprint(n * 2)
	})
	fmt.Println("doubled:", doubled)

	// 简单替换：把所有数字替换为 "#"。
	masked := numberRe.ReplaceAllString(src, "#")
	fmt.Println("masked: ", masked)

	// 用连续空白分割。
	parts := spaceRe.Split("one   two\tthree  four", -1)
	fmt.Println("split count:", len(parts))
	for i, p := range parts {
		fmt.Printf("  [%d]=%s\n", i, p)
	}
}

// T096 文本模板 text/template。
//
// text/template 用 {{.Field}} 占位符渲染结构化数据。模板可包含
// 条件 {{if}}、循环 {{range}}。本示例把渲染结果写入 bytes.Buffer，
// 再统一打印——不直接依赖 os.Stdout 捕获，输出因此确定、易测试。
package main

import (
	"bytes"
	"fmt"
	"text/template"
)

func main() {
	const tpl = `Inventory for {{.Owner}}:
{{range .Items}}- {{.Name}} x{{.Qty}} ({{if .InStock}}in stock{{else}}out of stock{{end}})
{{end}}Total lines: {{len .Items}}`

	data := struct {
		Owner string
		Items []struct {
			Name    string
			Qty     int
			InStock bool
		}
	}{
		Owner: "warehouse-a",
		Items: []struct {
			Name    string
			Qty     int
			InStock bool
		}{
			{"bolt", 100, true},
			{"nut", 0, false},
		},
	}

	t := template.Must(template.New("inv").Parse(tpl))

	// 渲染到内存缓冲，再打印，避免依赖底层 stdout 的捕获方式。
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		panic(err)
	}
	fmt.Println(buf.String())
}

