package tabletest

import "testing"

// Add 是被测函数。
func Add(a, b int) int { return a + b }

func TestAdd(t *testing.T) {
	cases := []struct {
		name string
		a, b int
		want int
	}{
		{"positive", 2, 3, 5},
		{"with zero", 0, 7, 7},
		{"negative", -2, -3, -5},
		{"mixed", -4, 4, 0},
	}
	for _, c := range cases {
		// t.Run 为每组数据建立独立子测试，名字唯一。
		t.Run(c.name, func(t *testing.T) {
			if got := Add(c.a, c.b); got != c.want {
				t.Fatalf("Add(%d,%d) = %d, want %d", c.a, c.b, got, c.want)
			}
		})
	}
}

