package stubtest

import (
	"errors"
	"testing"
)

// Store 是被依赖的接口。
type Store interface {
	Get(key string) (string, error)
}

// Service 通过接口使用 Store。
type Service struct{ store Store }

// Lookup 读取 key 并在缺失时返回统一错误。
func (s *Service) Lookup(key string) (string, error) {
	v, err := s.store.Get(key)
	if err != nil {
		return "", err
	}
	return v, nil
}

// stubStore 是测试桩：用 map 提供确定数据，并可配置返回错误。
type stubStore struct {
	data map[string]string
	err  error
}

func (s stubStore) Get(key string) (string, error) {
	if s.err != nil {
		return "", s.err
	}
	v, ok := s.data[key]
	if !ok {
		return "", errors.New("not found")
	}
	return v, nil
}

func TestLookupSuccess(t *testing.T) {
	svc := &Service{store: stubStore{data: map[string]string{"a": "1"}}}
	v, err := svc.Lookup("a")
	if err != nil || v != "1" {
		t.Fatalf("Lookup(a) = %q,%v", v, err)
	}
}

func TestLookupNotFound(t *testing.T) {
	svc := &Service{store: stubStore{data: map[string]string{}}}
	if _, err := svc.Lookup("missing"); err == nil {
		t.Fatal("expected error for missing key")
	}
}

func TestLookupStoreFailure(t *testing.T) {
	sentinel := errors.New("backend down")
	svc := &Service{store: stubStore{err: sentinel}}
	_, err := svc.Lookup("a")
	if !errors.Is(err, sentinel) {
		t.Fatalf("err = %v, want sentinel", err)
	}
}

// 导入后入口和同包辅助源码位于 src/，模块及子包保留根目录布局。
// T112 内存分配与逃逸分析。
//
// 编译器决定一个变量分配在栈还是堆上。若变量"逃逸"到函数外（被返回、
// 存入接口、被闭包长期捕获等），就分配到堆。用
//   go build -gcflags=-m
// 可查看逃逸报告。本示例给出可对比的两种写法。
//
// module-project 工程例子，导入时附带辅助文件。原始结构：
//   escapeanalyze/
//   ├── go.mod   // module escapeanalyze\n\ngo 1.27
//   └── main.go  // 本文件
// 运行（官方 SDK）：
//   go run .
//   go build -gcflags=-m .    // 查看逃逸报告
// 普通入口展示结果；逃逸分析报告使用桌面官方工具链。
package main

import "fmt"

// Point 是小的值类型。
type Point struct{ X, Y int }

// makeValue 按值返回：调用方拿到副本。
func makeValue() Point {
	p := Point{1, 2} // 可能留在栈上
	return p
}

// makePointer 返回指针：p 逃逸到堆。
func makePointer() *Point {
	p := Point{3, 4} // 逃逸：地址被返回
	return &p
}

// makeInterface 存入接口：通常逃逸（接口值在堆上）。
func makeInterface() any {
	p := Point{5, 6}
	return p
}

func main() {
	v := makeValue()
	fmt.Println("value:", v.X, v.Y)

	p := makePointer()
	fmt.Println("pointer:", p.X, p.Y)

	var a any = makeInterface()
	fmt.Println("interface:", a)

	fmt.Println("hint: `go build -gcflags=-m .` shows which variables escape to the heap")
}

