// T114 性能优化范式：预分配、批处理、零拷贝。
//
// 常见优化：用预分配切片（make([]T, 0, n)）避免反复扩容；
// 用 strings.Builder 拼接避免多次分配；用复用缓冲避免重复分配。
// 断言策略：功能等价断言（输出正确）+ 基准只作参考，不作通过条件。
//
// test-package / benchmark 工程例子，导入时附带辅助文件。原始结构：
//   perfpatterns/
//   ├── go.mod           // module perfpatterns\n\ngo 1.27
//   └── patterns_test.go // 本文件
// 运行（官方 SDK）：
//   go test ./...
//   go test -bench . -benchmem ./...
// 内置运行器执行有界基准循环；性能测量与比较使用官方工具链。
package perfpatterns

import (
	"strings"
	"testing"
)

// appendNoPrealloc 不预分配，靠 append 扩容。
func appendNoPrealloc(n int) []int {
	var s []int
	for i := 0; i < n; i++ {
		s = append(s, i)
	}
	return s
}

// appendPrealloc 预分配容量，减少扩容次数。
func appendPrealloc(n int) []int {
	s := make([]int, 0, n)
	for i := 0; i < n; i++ {
		s = append(s, i)
	}
	return s
}

// joinConcat 用 + 拼接。
func joinConcat(parts []string) string {
	out := ""
	for _, p := range parts {
		out += p
	}
	return out
}

// joinBuilder 用 strings.Builder 拼接。
func joinBuilder(parts []string) string {
	var b strings.Builder
	for _, p := range parts {
		b.WriteString(p)
	}
	return b.String()
}

func TestEquivalence(t *testing.T) {
	a := appendNoPrealloc(10)
	b := appendPrealloc(10)
	if len(a) != len(b) {
		t.Fatalf("lengths differ: %d vs %d", len(a), len(b))
	}
	for i := range a {
		if a[i] != b[i] {
			t.Fatalf("element %d differs", i)
		}
	}
	parts := []string{"a", "b", "c"}
	if joinConcat(parts) != joinBuilder(parts) {
		t.Fatal("join results differ")
	}
}

func BenchmarkAppendNoPrealloc(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = appendNoPrealloc(256)
	}
}

func BenchmarkAppendPrealloc(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = appendPrealloc(256)
	}
}

// T115 静态检查与工程规范：vet 与 gofmt 基线。
//
// gofmt 统一格式（-l 列出不合规文件，-d 显示 diff）；
// go vet 检查可疑构造（如 Printf 参数不匹配、无用的锁拷贝）。
// 二者是标准库工具链自带的静态检查基线，不依赖第三方。
//
// single-file 示例：本文件本身可由 CodeSnippet 导入；同时用作
// `gofmt`/`go vet` 的检查对象。
//
// 运行（官方 SDK）：
//   gofmt -l .
//   go vet ./...
// 下列命令使用官方工具链；单文件程序可直接导入运行。
package main

import "fmt"

func main() {
	// 正确格式：注意切片字面量对齐由 gofmt 统一。
	nums := []int{1, 2, 3}
	total := 0
	for _, n := range nums {
		total += n
	}
	fmt.Println("total:", total)

	// 演示 vet 会关注的正确写法：Printf 动词与参数类型匹配。
	name := "gopher"
	fmt.Printf("hello, %s (%d items)\n", name, len(nums))

	fmt.Println("run: `gofmt -l .` and `go vet ./...`")
}

// T116 日志与可观测性基线：log/slog。
//
// log/slog（Go 1.21+）提供结构化日志：键值对可被机器检索。
// 可设置级别（Info/Warn/Error），并选择 Text 或 JSON handler。
//
// 为让输出确定且可被任何运行环境捕获，本示例把日志写入 bytes.Buffer
// （而非直接写 os.Stdout），并用 ReplaceAttr 去掉默认的时间戳字段——
// 日志时间依赖运行时刻，不能作为固定输出。
package main

import (
	"bytes"
	"fmt"
	"log/slog"
)

// dropTime 删除 slog 默认的 time 属性，使输出与运行时刻无关。
func dropTime(_ []string, a slog.Attr) slog.Attr {
	if a.Key == slog.TimeKey {
		return slog.Attr{} // 空 Attr 会被忽略
	}
	return a
}

func main() {
	var buf bytes.Buffer
	opts := &slog.HandlerOptions{Level: slog.LevelInfo, ReplaceAttr: dropTime}

	// Text handler，级别 Info；输出写入内存缓冲。
	logger := slog.New(slog.NewTextHandler(&buf, opts))

	logger.Info("server starting", "addr", "127.0.0.1:8080", "pid", 1)
	logger.With("component", "db").Warn("slow query", "ms", 120)
	logger.Debug("this is filtered out") // 低于 Info，被过滤

	// JSON handler，级别 Error；同一缓冲区继续追加。
	jsonLogger := slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{
		Level:       slog.LevelError,
		ReplaceAttr: dropTime,
	}))
	jsonLogger.Error("failed to connect", "host", "db1")

	logger.Info("shutdown complete")

	// 一次性打印全部结构化日志，输出确定。
	fmt.Print(buf.String())
}

// T117 配置、标志与环境变量。
//
// flag 解析命令行参数；环境变量常用于容器/CI 注入配置。
// 常见优先级：命令行标志优先于环境变量，环境变量优先于默认值。
// 本示例构造确定参数并打印生效配置，输出确定（不读真实环境）。
package main

import (
	"flag"
	"fmt"
	"os"
)

// config 是最终生效的配置。
type config struct {
	Addr  string
	Level string
	Port  int
}

// loadConfig 依次从默认值、环境变量、命令行标志解析配置。
func loadConfig(args []string, getenv func(string) string) (config, error) {
	c := config{Addr: "127.0.0.1", Level: "info", Port: 8080}

	// 环境变量层。
	if v := getenv("APP_ADDR"); v != "" {
		c.Addr = v
	}
	if v := getenv("APP_LEVEL"); v != "" {
		c.Level = v
	}

	// 命令行标志层（优先级最高）。
	fs := flag.NewFlagSet("demo", flag.ContinueOnError)
	addr := fs.String("addr", c.Addr, "listen address")
	level := fs.String("level", c.Level, "log level")
	port := fs.Int("port", c.Port, "listen port")
	if err := fs.Parse(args); err != nil {
		return config{}, err
	}
	c.Addr, c.Level, c.Port = *addr, *level, *port
	return c, nil
}

func main() {
	// 模拟环境变量：通过注入的 getenv 获得确定性。
	env := map[string]string{"APP_ADDR": "10.0.0.1", "APP_LEVEL": "warn"}
	getenv := func(k string) string { return env[k] }

	// 仅带命令行标志覆盖（应覆盖 env 的 addr）。
	c, err := loadConfig([]string{"-addr", "192.168.1.5", "-port", "9000"}, getenv)
	if err != nil {
		panic(err)
	}
	fmt.Printf("addr=%s level=%s port=%d\n", c.Addr, c.Level, c.Port)

	// 不带标志时，环境变量生效。
	c2, _ := loadConfig(nil, getenv)
	fmt.Printf("addr=%s level=%s port=%d\n", c2.Addr, c2.Level, c2.Port)

	// 无 env、无标志时，默认值生效。
	c3, _ := loadConfig(nil, func(string) string { return "" })
	fmt.Printf("addr=%s level=%s port=%d\n", c3.Addr, c3.Level, c3.Port)

	_ = os.Getenv // 说明真实环境变量读法；此处为确定性不直接使用。
}

// 导入后入口和同包辅助源码位于 src/，模块及子包保留根目录布局。
// T118 综合项目一：命令行待办清单（CLI + JSON 持久化）。
//
// 整合：命令分发、JSON 持久化、错误处理。待办项存为 JSON 文件，
// 增/删/列/完成操作后落盘，重载后状态一致。
//
// module-project 工程例子，导入时附带辅助文件。原始结构：
//   todoapp/
//   ├── go.mod        // module todoapp\n\ngo 1.27
//   ├── main.go       // 本文件：CLI 入口
//   ├── store.go      // 文件存储
//   └── store_test.go // 端到端测试
// 运行（官方 SDK）：
//   go run . add "learn go"
//   go run . list
//   go test ./...
// 普通入口演示文件操作，选中 store_test.go 运行相应测试。
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

// Item 是一条待办。
type Item struct {
	ID   int    `json:"id"`
	Text string `json:"text"`
	Done bool   `json:"done"`
}

// Store 是待办存储。
type Store struct {
	path  string
	items []Item
}

// Load 从文件加载；文件不存在时返回空存储。
func Load(path string) (*Store, error) {
	s := &Store{path: path}
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return s, nil
	}
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(data, &s.items); err != nil {
		return nil, fmt.Errorf("decode %s: %w", path, err)
	}
	return s, nil
}

// Save 原子落盘：先写临时文件再改名，避免半写状态。
func (s *Store) Save() error {
	if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(s.items, "", "  ")
	if err != nil {
		return err
	}
	tmp := s.path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, s.path)
}

// Add 追加一条并返回其 id。
func (s *Store) Add(text string) int {
	id := 1
	for _, it := range s.items {
		if it.ID >= id {
			id = it.ID + 1
		}
	}
	s.items = append(s.items, Item{ID: id, Text: text})
	return id
}

// Complete 标记完成；找不到返回错误。
func (s *Store) Complete(id int) error {
	for i := range s.items {
		if s.items[i].ID == id {
			s.items[i].Done = true
			return nil
		}
	}
	return fmt.Errorf("item %d not found", id)
}

// Items 返回按 id 排序的副本，保证输出确定。
func (s *Store) Items() []Item {
	out := append([]Item(nil), s.items...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func main() {
	// 演示：用临时目录中的固定文件完成一轮增改查并重载。
	dir, err := os.MkdirTemp("", "qfli-t118-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "todo.json")

	st, err := Load(path)
	if err != nil {
		panic(err)
	}
	st.Add("learn go")
	st.Add("write tests")
	if err := st.Complete(1); err != nil {
		panic(err)
	}
	if err := st.Save(); err != nil {
		panic(err)
	}

	// 重载并打印，证明持久化一致。
	reloaded, err := Load(path)
	if err != nil {
		panic(err)
	}
	for _, it := range reloaded.Items() {
		status := "todo"
		if it.Done {
			status = "done"
		}
		fmt.Printf("%d [%s] %s\n", it.ID, status, it.Text)
	}
}

