	if err != nil {
		t.Fatalf("reload: %v", err)
	}
	items := reloaded.Items()
	if len(items) != 2 {
		t.Fatalf("items = %d, want 2", len(items))
	}
	if !items[0].Done || items[1].Done {
		t.Fatalf("done flags wrong: %+v", items)
	}

	// 完成不存在的 id 应报错。
