func TestTimeEndpointRejectsPost(t *testing.T) {
	var log []string
	h := NewHandler(fixedNow, &log)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/api/time", nil))

