        }
        throw new IllegalStateException("unknown shape");
    }

    static String describe(Shape shape) {
        if (shape instanceof Circle circle) {
            return "圆 r=" + circle.radius;
        }
        return "正方形 side=" + ((Square) shape).side;
    }

