public class Main {
    static <T> void copy(List<? super T> sink, List<? extends T> source) {
        for (T value : source) {
            sink.add(value);
        }
    }

    static double sum(List<? extends Number> numbers) {
        double total = 0;
        for (Number number : numbers) {
            total += number.doubleValue();
        }
        return total;
    }

    public static void main(String[] args) {
