def make_dataclass2(*fields):
    names, defaults = [], {}
    for field in fields:
        name = field[0] if isinstance(field, tuple) else field
        if name in names:
            raise ValueError("duplicate field")
        names.append(name)
        if isinstance(field, tuple):
            if len(field) != 2:
                raise ValueError("field needs name and default")
            defaults[name] = field[1]

    def decorate(cls):
        def initialize(self, *args, **kwargs):
            if len(args) > len(names):
                raise TypeError("too many values")
            values = dict(defaults)
            for i, value in enumerate(args):
                if names[i] in kwargs:
                    raise TypeError("duplicate value")
                values[names[i]] = value
            for name in kwargs:
                if name not in names:
                    raise TypeError("unknown field")
                values[name] = kwargs[name]
            if any(name not in values for name in names):
                raise TypeError("missing field")
            for name in names:
                setattr(self, name, values[name])
        cls.__init__ = initialize
        cls.__fields = tuple(names)
        return cls
    return decorate

