def make_dataclass(*names):
    def decorate(cls):
        ns = {}
        params = ", ".join(names)
        assigns = "\n    ".join("self.%s = %s" % (n, n) for n in names)
        exec("def __init__(self, " + params + "):\n    " + assigns, ns)
        cls.__init__ = ns["__init__"]
        cls.__fields = names

        def __repr__(self):
            inner = ", ".join(
                "%s=%r" % (n, getattr(self, n)) for n in names)
            return cls.__name__ + "(" + inner + ")"

        cls.__repr__ = __repr__

        def __eq__(self, other):
            return type(self) is type(other) and all(
                getattr(self, n) == getattr(other, n) for n in names)

        cls.__eq__ = __eq__
        cls.__hash__ = lambda self: hash(
            tuple(getattr(self, n) for n in names))
        return cls
    return decorate


def ordered(*names):
    def decorate(cls):
        cls = make_dataclass(*names)(cls)
        def less(self, other):
            if type(self) is not type(other):
                return NotImplemented
            return tuple(getattr(self, n) for n in names) < tuple(getattr(other, n) for n in names)
        cls.__lt__ = less
        return cls
    return decorate

@ordered("x", "y")
class Point:
    pass

