class BFS:
    def __init__(self, root):
        self.queue = [] if root is None else [root]
        self.index = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.index == len(self.queue):
            raise StopIteration
        node = self.queue[self.index]
        self.index += 1
        self.queue.extend(node.children)
        return node.name

