    def __iter__(self):
        return DepthFirst(self.root)

    def leaves(self):
        stack = [] if self.root is None else [self.root]
        result = []
        while stack:
            node = stack.pop()
            if not node.children:
                result.append(node.name)
            stack.extend(reversed(node.children))
        return result

