import collections


def check_brackets(text):
    stack = []
    pairs = {")": "(", "]": "[", "}": "{"}
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


def window_averages(values, k):
    q = collections.deque((), k)
    total = 0
    result = []
    for v in values:
        if len(q) == k:
            total -= q.popleft()
        q.append(v)
        total += v
        if len(q) == k:
            result.append(round(total / k, 1))
    return result


