def eval_rpn(tokens):
    stack = []
    for token in tokens:
        if token in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError("missing operand")
            right, left = stack.pop(), stack.pop()
            if token == "+": value = left + right
            elif token == "-": value = left - right
            elif token == "*": value = left * right
            else: value = left / right
            stack.append(value)
        else:
            stack.append(int(token))
    if len(stack) != 1:
        raise ValueError("invalid expression")
    return stack[0]

