def unbounded(weights, values, capacity):
    if capacity < 0 or len(weights) != len(values) or any(w <= 0 for w in weights):
        raise ValueError("invalid knapsack input")
    best = [0] * (capacity + 1)
    for c in range(1, capacity + 1):
        for i in range(len(weights)):
            if c >= weights[i]:
                best[c] = max(best[c], best[c - weights[i]] + values[i])
    return best[capacity]

