        r, c = queue[head]
        head += 1
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in seen:
                seen.add((nr, nc))
                queue.append((nr, nc))
    return queue

def solve_maze(grid, start, goal, allow_shortcut=False):
    if not grid or not grid[0]:
        return None
    rows, cols = len(grid), len(grid[0])
    if any(len(row) != cols for row in grid):
        raise ValueError("ragged maze")
    def walkable(cell):
        r, c = cell
        return 0 <= r < rows and 0 <= c < cols and (grid[r][c] == 0 or allow_shortcut and grid[r][c] == 2)
    if not walkable(start) or not walkable(goal):
        return None
    queue, parent, head = [start], {start: None}, 0
    while head < len(queue):
        r, c = queue[head]
        head += 1
        if (r, c) == goal:
            break
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            cell = (r + dr, c + dc)
            if walkable(cell) and cell not in parent:
                parent[cell] = (r, c)
                queue.append(cell)
    if goal not in parent:
        return None
    path, cell = [], goal
    while cell is not None:
        path.append(cell)
        cell = parent[cell]
    return path[::-1]

