def det(matrix):
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        raise ValueError("square matrix required")
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    total = 0
    for column in range(n):
        minor = [row[:column] + row[column + 1:] for row in matrix[1:]]
        total += (-1) ** column * matrix[0][column] * det(minor)
    return total

