def run_budget(tasks, max_steps):
    if max_steps < 0:
        raise ValueError("budget must be nonnegative")
    pending, events = list(tasks), []
    while pending:
        if len(events) == max_steps:
            for task in pending:
                task.close()
            return events, False
        task = pending.pop(0)
        try:
            events.append(next(task))
            pending.append(task)
        except StopIteration:
            pass
    return events, True

