import 'dart:io';

int countFiles(Directory dir) {
  var count = 0;
  for (final entity in dir.listSync()) {
    if (entity is File) {
      count++;
    } else if (entity is Directory) {
      count += countFiles(entity);
    }
  }
  return count;
}

void main() {
  final root = Directory.systemTemp.createTempSync('qfli_io_103_');
  try {
    final sub = Directory('${root.path}/sub')..createSync();
    File('${root.path}/a.txt').writeAsStringSync('a');
    File('${root.path}/sub/b.txt').writeAsStringSync('b');
    File('${root.path}/sub/c.txt').writeAsStringSync('c');
    print(sub.existsSync());
    print('文件总数 ${countFiles(root)}');
  } finally {
    root.deleteSync(recursive: true);
  }
}

