SELECT name, v FROM counters;

CREATE TABLE t (id INT PRIMARY KEY, s VARCHAR(64));
INSERT INTO t VALUES (1,'Alice');
SELECT id, CONCAT(s, '@example.com') AS email, CHAR_LENGTH(s) AS n FROM t;

CREATE TABLE shipments (id INT PRIMARY KEY, shipped_at DATE);
INSERT INTO shipments VALUES (1,'2026-01-01');
SELECT id, DATE_ADD(shipped_at, INTERVAL 1 DAY) AS eta, DATEDIFF('2026-01-05', shipped_at) AS days FROM shipments;

CREATE TABLE t (id INT PRIMARY KEY, v INT);
INSERT INTO t VALUES (1,10);
SELECT @@transaction_isolation AS level;

CREATE TABLE s (id INT PRIMARY KEY, region VARCHAR(16), product VARCHAR(16));
INSERT INTO s VALUES (1,'north','pen'),(2,'north','book'),(3,'south','bag');
SELECT region, GROUP_CONCAT(product ORDER BY product ASC SEPARATOR ',') AS products FROM s GROUP BY region ORDER BY region;

CREATE TABLE a (id INT PRIMARY KEY, v VARCHAR(8));
CREATE TABLE b (id INT PRIMARY KEY, v VARCHAR(8));
INSERT INTO a VALUES (1,'x'),(2,'y');
INSERT INTO b VALUES (2,'p'),(3,'q');
SELECT a.id, a.v, b.v FROM a LEFT JOIN b ON a.id=b.id
UNION
SELECT b.id, a.v, b.v FROM a RIGHT JOIN b ON a.id=b.id
ORDER BY 1;

